css:
.flex {
  display: flex
}

.grid {
  display: grid
}

.h-screen {
  height: 100vh
}

.w-full {
  width: 100%
}

.items-center {
  align-items: center
}

.justify-center {
  justify-content: center
}

.gap-3 {
  gap: 0.75rem
}

.gap-6 {
  gap: 1.5rem
}

.border-\[\#035ec5\] {
  --tw-border-opacity: 1;
  border-color: rgb(3 94 197 / var(--tw-border-opacity))
}

.bg-\[\#ffffff42\] {
  background-color: #ffffff42
}

.p-3 {
  padding: 0.75rem
}

.px-7 {
  padding-left: 1.75rem;
  padding-right: 1.75rem
}

.font-bold {
  font-weight: 700
}

.capitalize {
  text-transform: capitalize
}

.text-black {
  --tw-text-opacity: 1;
  color: rgb(0 0 0 / var(--tw-text-opacity))
}

.shadow-2xl {
  --tw-shadow: 0 25px 50px -12px rgb(0 0 0 / 0.25);
  --tw-shadow-colored: 0 25px 50px -12px var(--tw-shadow-color);
  box-shadow: var(--tw-ring-offset-shadow, 0 0 #0000), var(--tw-ring-shadow, 0 0 #0000), var(--tw-shadow)
}

.outline-none {
  outline: 2px solid transparent;
  outline-offset: 2px
}

.placeholder\:text-black::placeholder {
  --tw-text-opacity: 1;
  color: rgb(0 0 0 / var(--tw-text-opacity))
}

.hover\:border-\[1px\]:hover {
  border-width: 1px
}

.hover\:border-solid:hover {
  border-style: solid
}

.hover\:border-\[\#035ec5\]:hover {
  --tw-border-opacity: 1;
  border-color: rgb(3 94 197 / var(--tw-border-opacity))
}

.hover\:text-\[\#035ec5\]:hover {
  --tw-text-opacity: 1;
  color: rgb(3 94 197 / var(--tw-text-opacity))
}

.focus\:border-\[1px\]:focus {
  border-width: 1px
}

.focus\:border-solid:focus {
  border-style: solid
}
